import { defineConfig } from "vite-plus";

// Compiled Paraglide output, committed so check and test work on a clean checkout (packages/i18n/README.md),
// and the TanStack Router route tree that apps/web's Vite plugin writes.
const generated = ["packages/i18n/src/paraglide/**", "apps/web/src/routeTree.gen.ts"];

export default defineConfig({
  // Skills are vendored from upstream (skills-lock.json); formatting them breaks their hashes.
  // `worker-configuration.d.ts` is generated by `wrangler types`.
  fmt: {
    // packages/ui CSS is generated from tokens.ts, the API reference from apps/api/src/openapi.ts and the SDK's
    // fixtures from apps/api/test/sdk-fixture.ts; a test keeps each in sync.
    ignorePatterns: [
      ".agents/**",
      ".claude/**",
      "skills-lock.json",
      "**/worker-configuration.d.ts",
      "packages/ui/src/*.css",
      "docs/api/openapi.json",
      "packages/sdk/tests/fixtures/*.json",
      ...generated,
    ],
  },
  lint: {
    ignorePatterns: [".agents/**", ".claude/**", "**/worker-configuration.d.ts", ...generated],
    jsPlugins: [{ name: "vite-plus", specifier: "vite-plus/oxlint-plugin" }],
    rules: { "vite-plus/prefer-vite-plus-imports": "error" },
    overrides: [
      {
        // Worker code renders messages per recipient (RFC 0008): the current locale is one variable per isolate,
        // shared by concurrent requests. Messages come from ./messages, which requires `{ locale }` on every call.
        files: [
          "apps/api/src/**",
          "apps/status-edge/src/**",
          "apps/relay/src/**",
          "apps/web/worker/**",
          "integrations/*/src/**",
        ],
        rules: {
          "no-restricted-imports": [
            "error",
            {
              paths: [
                {
                  name: "@freecorps/brigade-i18n",
                  importNames: [
                    "m",
                    "getLocale",
                    "setLocale",
                    "overwriteGetLocale",
                    "overwriteSetLocale",
                  ],
                  message:
                    "Server code shares one locale per isolate: import messages from @freecorps/brigade-i18n/messages and pass { locale }.",
                },
                {
                  name: "@freecorps/brigade-i18n/labels",
                  importNames: ["severityLabels", "incidentStatusLabels"],
                  message:
                    "Server code shares one locale per isolate: use serverSeverityLabels / serverIncidentStatusLabels, which require { locale }.",
                },
              ],
              patterns: [
                {
                  group: [
                    "@freecorps/brigade-i18n/incident",
                    "@freecorps/brigade-i18n/oncall",
                    "@freecorps/brigade-i18n/why-paged",
                    "@freecorps/brigade-i18n/auth",
                  ],
                  message:
                    "These UI helpers word text in the current locale, which on a Worker is shared by every request (RFC 0008).",
                },
              ],
            },
          ],
        },
      },
    ],
    options: { typeAware: true, typeCheck: true },
  },
  run: {
    cache: true,
    // Native mobile builds on this computer (apps/mobile/README.md). Never cached: their outputs live outside the
    // task graph, and a cached task's file-access tracking breaks Gradle, which then cannot start the shebang-less
    // `prefab_command` scripts AGP writes ("error=8, Exec format error").
    tasks: {
      "mobile:install": { command: "node scripts/mobile-install.mjs", cache: false },
      "mobile:build": { command: "node scripts/mobile-build.mjs", cache: false },
      // Setup scripts talk to a deployed instance (and wrangler): never cached, or a second run would replay the
      // first one's output instead of doing anything. Not cached also means every environment variable reaches them.
      "setup:first-user": { command: "node apps/api/scripts/create-first-user.mjs", cache: false },
      // RFC 0015 section 8 (apps/api README "Push relay"); TypeScript, so through vpx with the workspace's source.
      "setup:relay": {
        command:
          "NODE_OPTIONS=--conditions=@freecorps/source vpx apps/relay/scripts/setup-relay/index.ts",
        cache: false,
      },
    },
  },
});
